// One HTTP request per page, no hidden SDK retries, two-second page deadline.
// On failure reject the whole operation; never publish accumulated partial rows.
export async function listPublished(client) {
  const rows = [];
  let cursor;
  for (;;) {
    const signal = AbortSignal.timeout(2000);
    let query = client.from('fixture_articles').select('id,title,published,created_at')
      .eq('published', true).order('created_at').order('id').limit(50)
      .retry(false).abortSignal(signal);
    if (cursor) query = query.or(`created_at.gt.${cursor.created_at},and(created_at.eq.${cursor.created_at},id.gt.${cursor.id})`);
    const {data, error} = await query;
    if (error || !Array.isArray(data)) throw new Error('ARTICLE_LIST_INCOMPLETE');
    rows.push(...data);
    if (data.length < 50) return rows;
    cursor = data.at(-1);
  }
}

export async function signedFile(client, key) {
  try {
    const {data, error} = await client.storage.from('framework-private-files').createSignedUrl(key, 60);
    if (error || !data?.signedUrl) return {ok:false, code:'FILE_UNAVAILABLE'};
    return {ok:true, url:data.signedUrl};
  } catch { return {ok:false, code:'FILE_UNAVAILABLE'}; }
}

export async function searchSimilar(client, vector, k) {
  if (!Array.isArray(vector) || vector.length !== 8 || vector.some(v => !Number.isFinite(v)) || !vector.some(v => v !== 0) || !Number.isInteger(k) || k < 1) throw new Error('INVALID_VECTOR_QUERY');
  const {data, error} = await client.rpc('fixture_search_vectors', {query_vector: vector, result_count:k});
  if (error || !Array.isArray(data)) throw new Error('VECTOR_SEARCH_FAILED');
  return data;
}
